t.script:
document.addEventListener('DOMContentLoaded', () => {

    // ========helpful methods ========
    function showToast(message, type='info') {
        let container = document.getElementById('toast-container');
        if (!container) {
            container = document.createElement('div');
            container.id = 'toast-container';
            container.className = 'position-fixed top-0 end-0 p-3';
            container.style.zIndex = '2000';
            document.body.appendChild(container);
        }
        const toast = document.createElement('div');
        const color = type==='success'?'bg-success':type==='error'?'bg-danger':type==='warning'?'bg-warning text-dark':'bg-secondary';
        toast.className = `toast align-items-center text-white ${color} border-0 show mb-2`;
        toast.innerHTML = `

${message}
            `;
        container.appendChild(toast);
        setTimeout(()=>toast.remove(),4000);
    }

    function enableAutoExpand(input) {
        input.classList.add('auto-expand');
        const resize = () => { input.style.height='auto'; input.style.height = input.scrollHeight+'px'; };
        input.addEventListener('input', resize);
        resize();
    }

    document.querySelectorAll('.auto-expand').forEach(enableAutoExpand);

    // ======== experience , language, skills========
    const groups = [
        {prefix:'experience', label:'الخبرة', placeholder:'أدخل خبرة جديدة'},
        {prefix:'language', label:'اللغة', placeholder:'أدخل لغة جديدة'},
        {prefix:'skill', label:'المهارة', placeholder:'أدخل مهارة جديدة'}
    ];

    groups.forEach(g => {
        const list = document.getElementById(`${g.prefix}_list`);
        const addBtn = document.getElementById(`add_${g.prefix}`);
        const undoBtn = document.getElementById(`undo_delete_${g.prefix}`);
        const deleted = [];
        if (!list || !addBtn || !undoBtn) return;
        undoBtn.classList.add('d-none');

        //add new element
        addBtn.addEventListener('click', () => {
            const div = document.createElement('div');
            div.className = `${g.prefix}-item d-flex align-items-center gap-2 mb-2`;
            div.innerHTML = `
                `;
            list.appendChild(div);
            enableAutoExpand(div.querySelector('input'));
            showToast(`تمت إضافة ${g.label} جديدة`, 'info');
        });

        // remove element
        list.addEventListener('click', e => {
            const btn = e.target.closest(`.remove-${g.prefix}`);
            if (btn) {
                const item = btn.closest(`.${g.prefix}-item`);
                const val = item.querySelector('input').value;
                if (val) deleted.push(val);
                item.remove();
                if (deleted.length > 0) undoBtn.classList.remove('d-none');
                showToast(`تم حذف ${g.label}. يمكنك التراجع.`, 'warning');

            }
        });

        // undo removing elements
        undoBtn.addEventListener('click', () => {
            if (deleted.length > 0) {
                const last = deleted.pop();
                const div = document.createElement('div');
                div.className = `${g.prefix}-item d-flex align-items-center gap-2 mb-2`;
                div.innerHTML = `
                    `;
                list.appendChild(div);
                enableAutoExpand(div.querySelector('input'));
                if (deleted.length === 0) undoBtn.classList.add('d-none');
                showToast(`تم التراجع عن حذف ${g.label}`, 'success');

            }
        });
    });

    // ======== attachments ========
    const newInput = document.getElementById('new_attachments_input');
    const preview = document.getElementById('new_attachments_preview');
    const noFilesMsg = document.getElementById('no_new_files');
    const currentList = document.getElementById('current_attachments_list');
    const restoreBtn = document.getElementById('restore_attachments_btn');
    const removedInput = document.getElementById('removed_attachments');

    let newFiles = [];
    let removedAttachments = [];
    let removedElements = [];

    function updateInputFiles(){
        const dt = new DataTransfer();
        newFiles.forEach(f => dt.items.add(f));
        newInput.files = dt.files;
    }

    function renderNewFiles(){
        preview.innerHTML = '';
        if(newFiles.length === 0){
            noFilesMsg.style.display = 'block';
            return;
        }
        noFilesMsg.style.display = 'none';
        newFiles.forEach((file, idx) => {
            const div = document.createElement('div');
            div.className = 'd-flex justify-content-between align-items-center border-bottom py-1';
            div.innerHTML = `${file.name}
                ✖`;
            preview.appendChild(div);
        });
    }

    //delete new file
    preview.addEventListener('click', e => {
        if (e.target.closest('.remove-new-file')) {
            const idx = parseInt(e.target.closest('.remove-new-file').dataset.index);
            newFiles.splice(idx, 1);
            renderNewFiles();
            updateInputFiles();
        }
    });

    newInput.addEventListener('change', () => {
        const selected = Array.from(newInput.files);
        newFiles = [...newFiles, ...selected];
        renderNewFiles();
        updateInputFiles();
    });

     //remove attachments temporary
    if(currentList){
        currentList.addEventListener('click', e => {
            if(e.target.closest('.remove-current-attachment')){
                const li = e.target.closest('li');
                removedAttachments.push(li.dataset.id);
                removedElements.push(li);
                li.remove();
                removedInput.value = removedAttachments.join(',');
                restoreBtn.classList.remove('d-none');
            }
        });
    }

    //restore deleted attachments
    if(restoreBtn){
        restoreBtn.addEventListener('click', () => {
            removedElements.forEach(li => currentList.appendChild(li));
            removedElements = [];
            removedAttachments = [];
            removedInput.value = '';
            restoreBtn.classList.add('d-none');
        });
    }

});
